world_checks.acls_and_memberships_populated:
def check(world):
    st = world.state()
    members = st.get("slack_channel_members", [])
    if len(members) < 20:
        return f"expected at least 20 channel membership entries, got {len(members)}"
    c04_members = [m for m in members if m.get("channel_id") == "C04"]
    if len(c04_members) != 2:
        return f"expected exactly 2 leadership members for C04, got {len(c04_members)}"
    return None

