world_checks.clock_and_approvals_ready:
def check(world):
    st = world.state()
    clock = st.get("clock", [])
    if not clock or not clock[0].get("now"):
        return "clock is not initialized"
    approvals = st.get("slack_approvals", [])
    if not approvals:
        return "approvals collection is empty"
    return None

world_checks.messages_and_threads_populated:
def check(world):
    st = world.state()
    users = st.get("slack_users", [])
    roles = set(u.get("role") for u in users)
    expected_roles = {"director", "engineer", "product_manager", "designer", "qa_engineer", "devops_engineer", "technical_writer", "vp_engineering"}
    if not expected_roles.issubset(roles):
        return f"missing required roles in users collection: {expected_roles - roles}"
    return None
